<script setup lang="ts">import{onMounted,ref}from'vue';import PageHeader from'../../components/PageHeader.vue';import{client,errorMessage,requireData}from'../../../shared/api/client';import type{components}from'../../../shared/api/schema.gen';const value=ref<components['schemas']['RuntimeSettings']>();const proxies=ref('');const secret=ref('');const error=ref('');onMounted(async()=>{try{value.value=requireData(await client.GET('/api/admin/system'));proxies.value=value.value.trustedProxies.join('\n')}catch(cause){error.value=errorMessage(cause)}});async function save(){if(!value.value)return;value.value.trustedProxies=proxies.value.split('\n').map(v=>v.trim()).filter(Boolean);value.value.turnstileSecret=secret.value||undefined;try{requireData(await client.PUT('/api/admin/system',{body:value.value}));secret.value=''}catch(cause){error.value=errorMessage(cause)}}</script>
<template><PageHeader title="系统设置" description="只有确认的代理网段才能加入可信代理。密钥不会从接口返回。"/><p v-if="error" class="text-danger">{{ error }}</p><form v-if="value" class="grid max-w-2xl gap-4" @submit.prevent="save"><label>可信代理 CIDR<textarea v-model="proxies" rows="5" class="nw-input" /></label><label>Turnstile 站点密钥<input v-model="value.turnstileSiteKey" class="nw-input"></label><label>Turnstile 私钥<input v-model="secret" type="password" class="nw-input" placeholder="留空表示不修改"></label><label>每日花费上限<input v-model.number="value.dailySpendLimit" type="number" min="0" step="0.01" class="nw-input"></label><label>data 远程仓库<input v-model="value.gitRemote" type="url" class="nw-input"></label><label>备份小时<input v-model.number="value.backupHour" type="number" min="0" max="23" class="nw-input"></label><label>保留备份数<input v-model.number="value.backupKeep" type="number" min="1" max="365" class="nw-input"></label><button class="nw-button">保存系统设置</button></form></template>
